using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ReflexiveMindAchievementData", menuName = "Data/Achievements/ReflexiveMindAchievementData")]
public class ReflexiveMindAchievementData : AchievementData
{
	protected override bool UnlockCustomRequirementCheck()
	{
		if (ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentAreaIndex == 2)
		{
			return ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.OrbsMovedWholeBattleAmount == 0;
		}
		return false;
	}
}
